const rows = $input.all().map((item) => item.json || {}).filter((row) => row.enabled !== false);
const SOURCE_HASH = '7da077b68c608244f1ffdda6b4dc552fdeab725f8d7bcfa8abb69dd65ea1c937';
const LEGACY_SOURCE_HASH = '27b0dfe58c248c2a914ba01fc7ca5d299c2cc281965dd9c33f00279b6e7659c3';
const COMPAT_SOURCE_HASHES = new Set([SOURCE_HASH, LEGACY_SOURCE_HASH, 'a81559da9204875555eafeaa24a4e7b809650060423ebf2dd6ed222db2b92c58', '2196bed6d88fa907f930e71b80ce61ad61084287aea2fcbebbe806e5f3f604ce', 'aa8f7adc9a0073a63fb77fd52d57cadc58dc1bd8e633d00d1ca6cf576dc083ae', 'b1c0d48ab343dfebffb915ca7b939b3f03d4f7016fc59e89b419d453f9f3dc3c']);
const SUITE_VERSION = '2.0.0';
const forbiddenEventFields = ['body','message_text','history','email','phone','name','conversation_summary','raw_error','full_prompt','full_reply'];
const hash = (value) => {
  let h = 2166136261;
  for (const ch of String(value || '')) {
    h ^= ch.charCodeAt(0);
    h = Math.imul(h, 16777619);
  }
  return ('00000000' + (h >>> 0).toString(16)).slice(-8);
};
const parseJson = (value, label, failures) => {
  try { return JSON.parse(String(value || '{}')); }
  catch (error) { failures.push(label + '_JSON_INVALID'); return {}; }
};
const hasExpected = (expected, key) => Array.isArray(expected[key]) && expected[key].length > 0;
const hasText = (expected, key, matcher) => hasExpected(expected, key) && expected[key].some((value) => matcher.test(String(value)));
const runCase = (row) => {
  const failures = [];
  let output = '';
  let summary = '';
  let resultState = {};
  const input = parseJson(row.input_json, 'input', failures);
  const expected = parseJson(row.expected_json, 'expected', failures);
  const kind = String(input.kind || '');
  const context = input.context && typeof input.context === 'object' ? input.context : {};
  const action = String(input.action || '');
  const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(context.email || ''));
  if (!row.case_id) failures.push('CASE_ID_REQUIRED');
  const legacyFixture = String(row.suite_version || '') === '1.0.0' && String(row.source_hash || '') === LEGACY_SOURCE_HASH;
  const compatibleSource = COMPAT_SOURCE_HASHES.has(String(row.source_hash || ''));
  if (!legacyFixture && String(row.suite_version || '') !== SUITE_VERSION) failures.push('SUITE_VERSION_MISMATCH');
  if (!legacyFixture && !compatibleSource) failures.push('SOURCE_HASH_MISMATCH');
  if (!['discovery','catalog','solution','proposal','controls','idempotency','crm','insights','followup','integrity','objections','deduplication','selection'].includes(String(row.category || ''))) failures.push('CATEGORY_INVALID');
  if (!['critical','secondary'].includes(String(row.severity || ''))) failures.push('SEVERITY_INVALID');
  if (kind === 'discovery_missing') {
    if (!hasExpected(expected, 'contains')) failures.push('DISCOVERY_QUESTION_MISSING');
    if (!hasExpected(expected, 'notContains')) failures.push('DISCOVERY_NEGATIVE_ASSERTIONS_MISSING');
    if (context.business_type && context.project_goal && (!context.pain_point || /algo digital|algo|ayuda/i.test(String(context.project_goal)))) {
      if (!hasText(expected, 'contains', /qué (está pasando|quieres resolver)/i)) failures.push('DISCOVERY_AMBIGUOUS_GUARD_MISSING');
    }
  } else if (kind === 'discovery_complete') {
    if (Number(expected.summaryMax || 0) > 420) failures.push('SUMMARY_LIMIT_INVALID');
    if (!hasExpected(expected, 'contains') && !hasExpected(expected, 'notContains')) failures.push('DISCOVERY_COMPLETE_ASSERTIONS_MISSING');
  } else if (kind === 'profile') {
    if (!Array.isArray(expected.fields) || expected.fields.length < 3) failures.push('PROFILE_FIELDS_INCOMPLETE');
    if (!String(input.input || '').trim()) failures.push('PROFILE_INPUT_REQUIRED');
  } else if (kind === 'price_gate') {
    if (!hasText(expected, 'notContains', /\$1\.550\.000|\$2\.100\.000/)) failures.push('PRICE_GATE_MISSING');
  } else if (kind === 'no_inference') {
