    } else if (solution === 'pack_web_chatbot') {
      if (!hasText(expected, 'contains', /catálogo web y chatbot|combinación/i)) failures.push('PACK_SCOPE_RULE_INVALID');
    } else {
      failures.push('SOLUTION_VALUE_INVALID');
    }
  } else if (kind === 'prices') {
    const catalog = input.catalog && typeof input.catalog === 'object' ? input.catalog : {};
