      const packages = catalog.catalog_packages || {};
      const essential = Number(packages['PKG-ESSENTIAL']?.price_project || 0);
      const professional = Number(packages['PKG-PROFESSIONAL']?.price_project || 0);
      if (essential <= 0 || professional <= 0) {
        if (!hasText(expected, 'notContains', /\$0/)) failures.push('MISSING_PRICE_FALLBACK_INVALID');
      } else if (!hasText(expected, 'contains', /\$1\.550\.000/) || !hasText(expected, 'contains', /\$2\.100\.000/)) {
        failures.push('CATALOG_PRICE_ASSERTIONS_INCOMPLETE');
      }
    } else if (!hasExpected(expected, 'contains') ||
      !expected.contains.some((value) => String(value).toLowerCase().includes('antes de mostrarte precios')) ||
      !hasExpected(expected, 'notContains') ||
      !expected.notContains.some((value) => String(value).includes('$1.550.000')) ||
      !expected.notContains.some((value) => String(value).includes('$2.100.000'))) {
      failures.push('CATALOG_UNAVAILABLE_GUARD_INVALID');
    }
  } else if (kind === 'source_scan') {
    if (!hasExpected(expected, 'notContains') || expected.notContains.length < 5) failures.push('LEGACY_PRICE_ASSERTIONS_INCOMPLETE');
  } else if (kind === 'proposal_prereqs') {
    const canSendExpected = expected.canSend === true;
    const canSendActual = emailValid && Boolean(context.discovery_done) && Boolean(context.solution_shown);
