  } else if (kind === 'proposal_flag') {
    if (expected.before !== 'false' || expected.after !== 'true') failures.push('PROPOSAL_FLAG_TRANSITION_INVALID');
  } else if (kind === 'summary') {
    if (Number(expected.max || 0) > 420 || !hasExpected(expected, 'notContains')) failures.push('SUMMARY_CONTRACT_INVALID');
  } else if (kind === 'event_schema') {
    if (!Array.isArray(expected.forbidden) || expected.forbidden.length !== forbiddenEventFields.length) failures.push('EVENT_PRIVACY_CONTRACT_INVALID');
  } else if (kind === 'event_idempotence') {
    if (expected.unique !== true) failures.push('EVENT_IDEMPOTENCE_CONTRACT_INVALID');
  } else if (kind === 'daily_aggregation') {
    for (const key of ['unique_conversations','processed_messages','duplicate_messages','handoffs']) {
      if (!Number.isFinite(Number(expected[key]))) failures.push('DAILY_ASSERTION_INVALID_' + key);
    }
  } else if (kind === 'followup') {
    if (expected.dry_run !== true || expected.sent !== false) failures.push('FOLLOWUP_DRY_RUN_CONTRACT_INVALID');
  } else if (kind === 'error_policy') {
    if (expected.critical !== 'stopWorkflow' || expected.secondary !== 'continueErrorOutput') failures.push('ERROR_POLICY_CONTRACT_INVALID');
  } else if (kind === 'advanced_wave') {
    const feature = String(input.feature || '').toLowerCase();
    const advancedInput = input.input && typeof input.input === 'object' ? input.input : {};
    const bool = (value) => value === true || value === 1 || String(value || '').toLowerCase() === 'true';
    const result = {
      feature,
      active: false,
      staging_only: true,
      external_call: false,
      pii_persisted: false,
      status: 'blocked_until_staging_approval',
      reason_code: 'STAGING_CONTRACT_READY'
    };
    if (feature === 'media') {
      const supported = /^(audio|image)\//i.test(String(advancedInput.mime_type || ''));
      result.status = supported ? 'staging_media_contract_ready' : 'fallback_required';
      result.reason_code = supported ? 'MEDIA_MIME_ACCEPTED_NO_PROVIDER_CALL' : 'MEDIA_MIME_UNSUPPORTED';
    } else if (feature === 'calendar') {
      const consent = bool(advancedInput.consent);
      result.status = consent ? 'pending_confirmation' : 'consent_required';
      result.appointment_status = consent ? 'requested' : 'none';
      result.appointment_timezone = 'America/Bogota';
    } else if (feature === 'pdf') {
      const ready = bool(advancedInput.discovery_done) && bool(advancedInput.solution_confirmed) && bool(advancedInput.catalog_ready) && bool(advancedInput.proposal_requested);
      result.status = ready ? 'staging_pdf_contract_ready' : 'preconditions_required';
      result.reason_code = ready ? 'PDF_PRECONDITIONS_MET_NO_FILE_CREATED' : 'PDF_PRECONDITIONS_MISSING';
    } else if (feature === 'multichannel') {
      result.channel = String(advancedInput.channel || 'whatsapp').toLowerCase();
      result.status = result.channel === 'whatsapp' ? 'whatsapp_adapter_ready' : 'adapter_not_active';
      result.reason_code = result.channel === 'whatsapp' ? 'WHATSAPP_ONLY_ACTIVE_CHANNEL' : 'CHANNEL_DISABLED';
    } else if (feature === 'followup') {
      result.status = 'dry_run_only';
      result.dry_run = true;
      result.max_per_run = 3;
      result.reason_code = 'FOLLOWUP_REAL_SEND_BLOCKED';
    }
    for (const [key, value] of Object.entries(expected)) {
