    }
    output = JSON.stringify(result);
  } else if (kind === 'contract_v2') {
    const sourceText = Array.isArray(input.sequence) && input.sequence.length ? input.sequence.join(' \n ') : String(input.input || '');
    const lowerText = sourceText.toLowerCase();
    const has = (...values) => values.some((value) => lowerText.includes(value));
    const explicitPack = has('pack', 'ambos', 'los dos', 'web + chatbot', 'web y chatbot', 'chatbot + web', 'chatbot y web');
    const explicitChatbot = has('solo chatbot', 'necesito un chatbot', 'quiero un chatbot', 'chatbot whatsapp');
    const explicitWeb = has('solo web', 'solo la web', 'necesito una web', 'necesito una página', 'quiero una web', 'quiero web', 'catálogo web');
    const selected = explicitPack ? 'pack_web_chatbot' : explicitChatbot ? 'chatbot_whatsapp_ia' : explicitWeb ? 'web_catalogo' : '';
    const businessKnown = !lowerText.includes('tengo un negocio') && has('ropa', 'tienda', 'retail', 'restaurante', 'inmobiliaria', 'pcs', 'hardware', 'clínica', 'clinica', 'servicio');
    const goalKnown = has('chatbot', 'whatsapp', 'web', 'página', 'pagina', 'catálogo', 'catalogo', 'automatiz');
    const painKnown = has('pierdo', 'perdemos', 'no respondo', 'no respondemos', 'ventas', 'problema', 'dolor');
    const currentKnown = has('manual', 'manualmente', 'por whatsapp', 'atendemos', 'atiendo', 'sin sistema', 'redes');
    const outcomeKnown = has('quiero responder', 'quiero vender', 'responder más rápido', 'responder mas rapido', 'mejorar', 'no perder');
    const discoveryDone = businessKnown && goalKnown && painKnown && currentKnown && outcomeKnown;
    const objection = has('muy caro', 'está caro', 'esta caro', 'costoso') ? 'price_high' : '';
    const result = {
      discovery_done: discoveryDone,
      selected_solution: selected,
      proposal_sent: false,
      proposal_delivery_status: String(context.proposal_delivery_status || 'none'),
      proposal_accepted: false,
      objection_code: objection,
      human_required: /asesor|humano|persona real/.test(lowerText),
      bot_muted: /asesor|humano|persona real/.test(lowerText),
      opt_out: /no molestar|no me escribas|\bstop\b|\bbaja\b/.test(lowerText),
      pipeline_stage: /asesor|humano|persona real/.test(lowerText) ? 'handoff' : /no molestar|no me escribas/.test(lowerText) ? 'cerrado' : discoveryDone ? 'calificado' : 'descubrimiento'
    };
    if (action === 'proposal_gate' && result.proposal_delivery_status === 'sent') result.proposal_sent = true;
    if (action === 'proposal_gate' && result.proposal_delivery_status !== 'prepared') failures.push('PROPOSAL_STATUS_FIXTURE_INVALID');
