    if (action === 'ambiguous' && (businessKnown || goalKnown || selected)) failures.push('AMBIGUOUS_MESSAGE_ADVANCED');
    if (action === 'selection' && !selected) failures.push('EXPLICIT_SELECTION_MISSING');
    if (action === 'objection' && objection !== 'price_high') failures.push('OBJECTION_NOT_CLASSIFIED');
    output = JSON.stringify(result);
    for (const value of expected.notContains || []) if (output.includes(String(value))) failures.push('FORBIDDEN_TEXT_' + String(value));

  } else if (kind === 'closure_flow') {
    let state = { ...(context || {}) };
    const normalize = (value) => String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const parseTurn = (message) => {
      const raw = String(message || '').trim();
      const text = normalize(raw);
      const turn = {};
      if (/\b(vendo|tengo|manejo|es una)\b.*\b(ropa|tienda|retail)\b|\btienda de ropa\b/.test(text)) turn.business_type = 'tienda / retail';
      if (/^ventas?$/.test(text) || /\bventas\b/.test(text) && !/pierdo|perdemos/.test(text)) turn.project_goal = 'ventas';
      else if (/^atencion$/.test(text)) turn.project_goal = 'atención';
      else if (/^catalogo$/.test(text)) turn.project_goal = 'catalogo';
      else if (/^seguimiento$/.test(text)) turn.project_goal = 'seguimiento';
