        turn.selected_solution = 'chatbot_whatsapp_ia';
      }
      if (/solo\s+chatbot/.test(text)) {
        turn.selected_solution = 'chatbot_whatsapp_ia';
        turn.solution_confirmed = true;
      }
      if (/solo\s+(la\s+)?web|solo\s+catalogo/.test(text)) {
        turn.selected_solution = 'web_catalogo';
