        turn.solution_confirmed = true;
      }
      if (/pierdo\s+ventas|perdemos\s+ventas|no\s+respondo\s+(a\s+)?tiempo|respondo\s+tarde/.test(text)) {
        turn.pain_point = /no\s+respondo|respondo\s+tarde/.test(text) ? 'no respondo a tiempo' : 'pierdo ventas';
        turn.impact = /pierdo\s+ventas|perdemos\s+ventas/.test(text) ? 'pierdo ventas' : turn.impact;
      }
      if (/respondemos\s+manualmente\s+por\s+whatsapp|atendemos\s+manualmente|atencion\s+manual/.test(text)) turn.current_process = 'Respondemos manualmente por WhatsApp';
      if (/quiero\s+responder\s+mas\s+rapido|necesito\s+contestar\s+rapido|quiero\s+contestar\s+mas\s+rapido/.test(text)) turn.desired_outcome = 'Quiero responder más rápido';
      return turn;
    };
    for (const message of (Array.isArray(input.sequence) ? input.sequence : [])) {
      const turn = parseTurn(message);
      for (const key of ['business_type','project_goal','pain_point','current_process','impact','desired_outcome','selected_solution']) {
        if (turn[key]) state[key] = turn[key];
      }
      if (turn.solution_confirmed === true) state.solution_confirmed = true;
    }
    const hasPainImpact = Boolean(state.pain_point) && (Boolean(state.impact) || /pierdo|ventas|perdemos/.test(normalize(state.pain_point)));
    const discoveryDone = Boolean(state.business_type && state.project_goal && state.pain_point && state.current_process && state.desired_outcome);
    state.discovery_done = discoveryDone;
    state.discovery_depth = [state.business_type,state.project_goal,state.pain_point,state.current_process,state.impact,state.desired_outcome].filter(Boolean).length;
    const nextQuestion = !state.business_type ? 'business_type' : !state.project_goal ? 'project_goal' : !state.pain_point ? 'pain_point' : !state.current_process ? 'current_process' : !hasPainImpact && !state.discovery_urgency ? 'impact' : !state.desired_outcome ? 'desired_outcome' : 'solution';
    const questionText = {
      business_type: '¿A qué se dedica tu negocio?',
      project_goal: '¿Qué quieres resolver primero?',
      pain_point: '¿Qué está pasando hoy que te llevó a buscarlo?',
      current_process: '¿Cómo lo están resolviendo hoy y en qué momento se complica más?',
      impact: '¿Qué impacto tiene hoy en tu negocio o qué tan urgente es resolverlo?',
