    }[nextQuestion];
    summary = 'Entiendo: tienes ' + (state.business_type || 'un negocio') + ', quieres resolver ' + (state.project_goal || 'una necesidad') + (state.pain_point ? ' porque ' + state.pain_point : '') + (state.current_process ? '; hoy ' + state.current_process.toLowerCase() : '') + (state.desired_outcome ? ' y buscas ' + state.desired_outcome.toLowerCase() : '') + '.';
    summary = summary.slice(0, 420);
    resultState = { ...state, next_question_code: nextQuestion, next_question: questionText, summary };
    output = summary + '\n' + questionText;
  } else if (kind === 'closure_duplicate') {
    const seen = new Set();
    const claim = (event) => {
      const conversation = String(event.conversation_id || '').trim();
      const message = String(event.message_id || '').trim();
      const key = message ? conversation + '|' + message : conversation + '|fallback:' + String(event.body_hash || '') + ':' + String(event.minute_bucket || '');
      if (!conversation || seen.has(key)) return false;
      seen.add(key);
      return true;
    };
    const first = claim({ conversation_id: '9', message_id: 'm1', body_hash: 'same', minute_bucket: '1' });
    const repeated = claim({ conversation_id: '9', message_id: 'm1', body_hash: 'same', minute_bucket: '1' });
    const sameTextDifferentId = claim({ conversation_id: '9', message_id: 'm2', body_hash: 'same', minute_bucket: '1' });
    const fallbackFirst = claim({ conversation_id: '9', message_id: '', body_hash: 'fallback', minute_bucket: '2' });
    const fallbackRepeated = claim({ conversation_id: '9', message_id: '', body_hash: 'fallback', minute_bucket: '2' });
    resultState = { same_id_first: first, same_id_repeated: repeated, same_text_different_id: sameTextDifferentId, fallback_first: fallbackFirst, fallback_repeated: fallbackRepeated, accepted_count: [first,repeated,sameTextDifferentId,fallbackFirst,fallbackRepeated].filter(Boolean).length };
    output = JSON.stringify(resultState);
  } else if (kind === 'closure_price_gate') {
    const selected = String(context.selected_solution || '');
    const confirmed = context.solution_confirmed === true || String(context.solution_confirmed || '').toLowerCase() === 'true';
    const requested = context.price_requested === true || String(context.price_requested || '').toLowerCase() === 'true';
    const catalog = input.catalog && typeof input.catalog === 'object' ? input.catalog : {};
    const ready = catalog.catalog_ready === true && Number(catalog.catalog_packages?.['PKG-ESSENTIAL']?.price_project || 0) > 0 && Number(catalog.catalog_packages?.['PKG-PROFESSIONAL']?.price_project || 0) > 0;
    if (!confirmed || !requested || !ready) resultState = { can_show_prices: false, reason_code: 'DISCOVERY_OR_SELECTION_REQUIRED' };
    else if (selected === 'chatbot_whatsapp_ia' || selected === 'web_catalogo') resultState = { can_show_prices: false, reason_code: 'NO_INDEPENDENT_SKU', selected_solution: selected };
    else if (selected === 'pack_web_chatbot') {
      resultState = { can_show_prices: true, reason_code: 'PACK_CATALOG_READY', selected_solution: selected };
      output = 'Esencial: $1.550.000 + $220.000/mes\nProfesional: $2.100.000 + $280.000/mes';
    } else resultState = { can_show_prices: false, reason_code: 'SOLUTION_REQUIRED' };
    if (!output) output = JSON.stringify(resultState);
  } else if (kind === 'closure_proposal_gate') {
    const requested = context.proposal_requested === true || String(context.proposal_requested || '').toLowerCase() === 'true';
    const confirmed = context.solution_confirmed === true || String(context.solution_confirmed || '').toLowerCase() === 'true';
    const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(context.email || ''));
    const deliveryStatus = String(context.proposal_delivery_status || 'none').toLowerCase();
    resultState = { proposal_requested: requested, solution_confirmed: confirmed, email_valid: emailValid, delivery_status: deliveryStatus, proposal_sent: requested && confirmed && emailValid && deliveryStatus === 'sent' };
    output = JSON.stringify(resultState);
  } else if (kind === 'controls' || kind === 'duplicate' || kind === 'media') {
    if (!expected || typeof expected !== 'object' || !Object.keys(expected).length) failures.push('CONTROL_ASSERTIONS_MISSING');
  } else {
    failures.push('CASE_KIND_UNSUPPORTED');
  }
  const eventSample = {event_id:String(row.case_id || ''),event_type:'turn_processed',conversation_id:'synthetic',occurred_at:'2026-08-20T00:00:00-05:00'};
  for (const field of forbiddenEventFields) {
    if (Object.prototype.hasOwnProperty.call(eventSample, field)) failures.push('EVENT_PII_FIELD_' + field);
  }
  const outputSchemaOk = Boolean(row.case_id) && typeof row.category === 'string' && typeof expected === 'object';
  const eventSchemaOk = !forbiddenEventFields.some((field) => Object.prototype.hasOwnProperty.call(eventSample, field));
  return {
    case_id:String(row.case_id || ''),
    category:String(row.category || ''),
    passed:failures.length === 0,
    output_schema_ok:outputSchemaOk,
    event_schema_ok:eventSchemaOk,
    failed_assertions:failures.join(' | '),
    reply_hash:'fnv1a:' + hash(String(row.case_id || '') + '|' + String(row.expected_json || '')),
    duration_ms:0,
    error_code:failures[0] || ''
  };
};
const results = rows.map(runCase);
const failed = results.filter((result) => !result.passed);
const startedAt = new Date().toISOString();
const runId = 'staging-' + Date.now() + '-' + hash(rows.map((row) => row.case_id).join('|'));
return [{
  json: {
    run_id:runId,
    started_at:startedAt,
    finished_at:new Date().toISOString(),
    suite_version:SUITE_VERSION,
    source_hash:SOURCE_HASH,
    mode:'staging',
    workflow_id:String($workflow.id || ''),
    execution_id:String($execution.id || ''),
    total_cases:results.length,
    passed:results.filter((result) => result.passed).length,
    failed:failed.length,
    status:failed.length ? 'failed' : 'passed',
    error_message:failed.length ? failed.slice(0,5).map((result) => result.case_id + ':' + result.error_code).join('; ') : '',
    results
  }
}];
